print('\nDesigns keys:', list(designs.keys()) if isinstance(designs, dict) else 'list')
if isinstance(designs, dict):
    for key in designs:
        val = designs[key]
        if isinstance(val, list) and len(val) > 0:
            print(f'  designs.{key}[0] keys:', list(val[0].keys()) if isinstance(val[0], dict) else val[0])
